/** Wavefront OBJ + MTL writer. */
import type { MeshData } from '../core/mesh';
import { hexToRgb, srgbToLinear } from '../core/math';

const f = (x: number) => (Math.abs(x) < 1e-7 ? '0' : x.toFixed(6).replace(/\.?0+$/, ''));

export function exportOBJ(mesh: MeshData, name = 'Character', mtlFile = `${name}.mtl`): { obj: string; mtl: string } {
  const lines: string[] = [
    '# Generated by 3d-gen character generator',
    `# ${mesh.positions.length / 3} vertices`,
    `mtllib ${mtlFile}`,
    `o ${name}`,
  ];
  const P = mesh.positions, N = mesh.normals, T = mesh.uvs;
  for (let i = 0; i < P.length; i += 3) lines.push(`v ${f(P[i])} ${f(P[i + 1])} ${f(P[i + 2])}`);
  for (let i = 0; i < T.length; i += 2) lines.push(`vt ${f(T[i])} ${f(T[i + 1])}`);
  for (let i = 0; i < N.length; i += 3) lines.push(`vn ${f(N[i])} ${f(N[i + 1])} ${f(N[i + 2])}`);
  for (const g of mesh.groups) {
    const m = mesh.materials[g.material];
    lines.push(`g ${name}_${m.name}`, `usemtl ${m.name}`, 's 1');
    const I = g.indices;
    for (let i = 0; i < I.length; i += 3) {
      const a = I[i] + 1, b = I[i + 1] + 1, c = I[i + 2] + 1;
      lines.push(`f ${a}/${a}/${a} ${b}/${b}/${b} ${c}/${c}/${c}`);
    }
  }

  const mtl: string[] = ['# Generated by 3d-gen character generator'];
  for (const m of mesh.materials) {
    const [r, g, b] = hexToRgb(m.color).map(srgbToLinear);
    const ns = Math.round((1 - m.roughness) ** 2 * 900 + 4);
    mtl.push(
      '',
      `newmtl ${m.name}`,
      `Ka 0 0 0`,
      `Kd ${f(r)} ${f(g)} ${f(b)}`,
      `Ks ${f(0.04 + m.metalness * 0.5)} ${f(0.04 + m.metalness * 0.5)} ${f(0.04 + m.metalness * 0.5)}`,
      `Ns ${ns}`,
      `Pr ${f(m.roughness)}`,
      `Pm ${f(m.metalness)}`,
      'd 1',
      'illum 2',
    );
  }
  return { obj: lines.join('\n') + '\n', mtl: mtl.join('\n') + '\n' };
}
